INSERT INTO authors (author_id, name, surname, description, date_of_birth, country, picture_url) VALUES (1, 'Francis Scott', 'Fitzgerald', 'American novelist and short story writer, widely regarded as one of the greatest American writers of the 20th century.', '1896-09-24', 'us', 'https://example.com/photos/fitzgerald.jpg'), (2, 'Harper', 'Lee', 'American novelist best known for her Pulitzer Prize-winning novel To Kill a Mockingbird.', '1926-04-28', 'us', 'https://example.com/photos/harper_lee.jpg'), (3, 'George', 'Orwell', 'English novelist, essayist, journalist and critic known for his dystopian novels and sharp social commentary.', '1903-06-25', 'us', 'https://example.com/photos/orwell.jpg'), (4, 'Jane', 'Austen', 'English novelist known for her six major novels that critique and comment upon the British landed gentry.', '1775-12-16', 'us', 'https://example.com/photos/austen.jpg'), (5, 'Jerome David', 'Salinger', 'American writer best known for his novel The Catcher in the Rye.', '1919-01-01', 'us', 'https://example.com/photos/salinger.jpg');
