INSERT INTO books (book_id, name, isbn, total_pages, description, date_of_publish, picture_url) VALUES (1, 'The Great Gatsby', '9780743273565', 180, 'A story of the mysteriously wealthy Jay Gatsby and his love for the beautiful Daisy Buchanan.', '1925-04-10', 'https://example.com/covers/gatsby.jpg'), (2, 'To Kill a Mockingbird', '9780061120084', 281, 'The unforgettable novel of a childhood in a sleepy Southern town and the crisis of conscience that rocked it.', '1960-07-11', 'https://example.com/covers/mockingbird.jpg'), (3, '1984', '9780451524935', 328, 'A dystopian social science novel that follows the life of Winston Smith in a totalitarian society.', '1949-06-08', 'https://example.com/covers/1984.jpg'), (4, 'Pride and Prejudice', '9780141439518', 432, 'A romantic novel that charts the emotional development of Elizabeth Bennet as she learns about the consequences of hasty judgments.', '1813-01-28', 'https://example.com/covers/pride.jpg'), (5, 'The Catcher in the Rye', '9780316769488', 234, 'The story of Holden Caulfield and his teenage experiences in New York City.', '1951-07-16', 'https://example.com/covers/catcher.jpg');
