INSERT INTO reviews (review_id, book_id, user_id, rating, content) VALUES (1, 1, 'b2c3d4e5-0001-4000-8000-000000000001', 5, 'A masterpiece of American literature. The writing is beautiful and the themes are timeless.'), (2, 1, 'b2c3d4e5-0002-4000-8000-000000000002', 4, 'Great book, though the pacing can be slow at times. The character development is superb.'), (3, 2, 'b2c3d4e5-0002-4000-8000-000000000002', 5, 'An incredibly powerful and moving story. Everyone should read this at least once.'), (4, 3, 'b2c3d4e5-0001-4000-8000-000000000001', 5, 'Prophetic and disturbing. More relevant today than ever.'), (5, 4, 'b2c3d4e5-0003-4000-8000-000000000003', 3, 'Well-written but not my cup of tea. The social commentary is sharp though.'), (6, 5, 'b2c3d4e5-0003-4000-8000-000000000003', 4, 'A compelling look into teenage angst. Holden Caulfield is one of literatures most memorable characters.');
